  ('ROLE-CS', 'customer_success', 'Customer Success Professional', 'mid', false, true, true, 'Customer success role.'),
  ('ROLE-SUPPORT', 'customer_support', 'Customer / Technical Support Professional', 'mid', false, true, true, 'Customer or technical support role.'),
